}

// reinitializeViews drops every view so they are rebuilt against the current
// config, and returns the init cmd for the one on screen.
func (a *App) reinitializeViews() tea.Cmd {
	log.Printf("Reinitializing views with new config")
	a.views = make(map[command.ViewType]Screen)
	a.createView(a.currentView)

	var initCmd tea.Cmd
	if view, ok := a.views[a.currentView]; ok {
		initCmd = view.Init()
	}
	log.Printf("Views reinitialized successfully")
	return initCmd
}

// BlinkingView is implemented by a view with a row that blinks for a reason the
// registry does not know (an instant action, an agent running, children loading).
// The router asks the view on screen after every Update: a level, not an edge.
type BlinkingView interface {
	WantsBlink() bool
}

// Update is the router's only entry: the dispatch, then the level check of the
// animation chain. The view's own Cmd goes through untouched; ensureTick adds a
// Cmd only when a chain has to start or be replaced, and is idempotent, so a

	case tea.ColorProfileMsg:
		// Router state only (View sets the terminal background); not forwarded.
		a.colorProfile = msg.Profile
		return a, nil

	case tea.BlurMsg:
		return a.handleTerminalBlur()

	case tea.FocusMsg:
		return a.handleTerminalFocus()

	case tea.KeyPressMsg:
		a.handleTerminalFocus() // input proves the terminal has the focus
		return a.handleKeyMsg(msg)

	if newFooterHeight := a.getFooterHeight(); newFooterHeight != a.lastFooterHeight {
		a.resize(a.width, a.height)
	}
	return tea.Batch(cmds...)
}

// enterView hands a view that is entering the screen the snapshot and the
// current frame. Every path that installs a view without going through
// switchView calls it too, otherwise the view shows stale rows until the next
// change.
func (a *App) enterView(target command.ViewType) tea.Cmd {
	return tea.Batch(a.sendJobsTo(target), a.sendFrameTo(target))
}

// sendJobsTo hands the snapshot to one view, which is what a view entering the
// screen needs: it was updated where it stood, but a view built lazily on the
// way in was not there for any of it.
func (a *App) sendJobsTo(target command.ViewType) tea.Cmd {
	view, ok := a.views[target]
	if !ok {
		return nil
	}
	updated, cmd := view.Update(a.changedMsg())
	a.setView(target, updated)
	return cmd
}
